from fractions import Fraction

def pow_half(n: int) -> Fraction:
    """Dyadic value of the surreal power of one half 2^-n."""
    return Fraction(1, 2 ** n)

def birthday_pow_half(n: int) -> int:
    """Birthday of 2^-n in Conway's construction, equal to n + 1."""
    return n + 1

for n in range(9):
    print(f"2^-{n}: value={pow_half(n)}, birthday={birthday_pow_half(n)} (< omega)")

from fractions import Fraction

def pow_half(n: int) -> Fraction:
    return Fraction(1, 2 ** n)

def check_exponent_law(max_m: int = 6, max_n: int = 6) -> bool:
    """Verify 2^-m * 2^-n = 2^-(m+n) exactly over a grid of exponents."""
    for m in range(max_m + 1):
        for n in range(max_n + 1):
            if pow_half(m) * pow_half(n) != pow_half(m + n):
                return False
    return True

def check_rescaling(max_n: int = 12) -> bool:
    """Verify 2^n * 2^-n = 1 exactly."""
    return all((2 ** n) * pow_half(n) == 1 for n in range(max_n + 1))

print("exponent law:", check_exponent_law())
print("rescaling law:", check_rescaling())

from fractions import Fraction
from dataclasses import dataclass

@dataclass(frozen=True)
class Dyadic:
    numerator: int
    exponent: int
    @staticmethod
    def of_fraction(q: Fraction) -> "Dyadic":
        den, exp = q.denominator, 0
        while den % 2 == 0:
            den //= 2; exp += 1
        if den != 1:
            raise ValueError(f"{q} is not dyadic")
        return Dyadic(q.numerator, exp)
    def value(self) -> Fraction:
        return Fraction(self.numerator, 2 ** self.exponent)

def dyadic_map(d: Dyadic) -> Fraction:
    """Canonical embedding m/2^n -> m * 2^-n into the surreals."""
    return d.value()

samples = [Fraction(3,8), Fraction(-5,16), Fraction(7,4), Fraction(11,32)]
ds = [Dyadic.of_fraction(q) for q in samples]
ok_add = all(dyadic_map(Dyadic.of_fraction(a.value()+b.value())) ==
             dyadic_map(a)+dyadic_map(b) for a in ds for b in ds)
ok_mul = all(dyadic_map(Dyadic.of_fraction(a.value()*b.value())) ==
             dyadic_map(a)*dyadic_map(b) for a in ds for b in ds)
ok_inj = len({dyadic_map(d) for d in ds}) == len({d.value() for d in ds})
print("additive:", ok_add, "| multiplicative:", ok_mul, "| injective:", ok_inj)

