from fractions import Fraction

def pow_half(n: int) -> Fraction:
    """Value of 2^-n; recursively 2^0 = 1, 2^-(n+1) = {0 | 2^-n}."""
    return Fraction(1, 2 ** n)

def birthday_pow_half(n: int) -> int:
    """Return the birthday of 2^-n, provably equal to n + 1.

    Modeled directly from the recursion: 1 = {0 | } is born on day 1, and each
    simplest midpoint 2^-(n+1) = {0 | 2^-n} adds exactly one day.
    """
    birthday = 1              # birthday of 2^-0 = 1
    for _ in range(n):
        birthday += 1         # each midpoint costs one more day
    return birthday

